import{_ as t,a as o,o as d,a6 as a}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Checkout","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/shop/checkout/index.md","filePath":"api/rest-api/shop/checkout/index.md","lastUpdated":1787290888000}'),s={name:"api/rest-api/shop/checkout/index.md"};function r(h,e,c,i,n,p){return d(),o("div",null,e[0]||(e[0]=[a('<h1 id="checkout" tabindex="-1">Checkout <a class="header-anchor" href="#checkout" aria-label="Permalink to &quot;Checkout&quot;">​</a></h1><p>The Checkout menu turns a prepared cart into a placed order. It runs as a sequence: set the addresses, choose a shipping method, choose a payment method, then place the order.</p><h2 id="the-checkout-sequence" tabindex="-1">The checkout sequence <a class="header-anchor" href="#the-checkout-sequence" aria-label="Permalink to &quot;The checkout sequence&quot;">​</a></h2><p>Checkout is order-sensitive — each step unlocks the next:</p><ol><li><strong>Set the shipping and billing addresses</strong> (or read back the saved ones). Addresses are required before shipping rates can be calculated.</li><li><strong>Get shipping methods</strong> for the cart, then <strong>set</strong> the chosen one.</li><li><strong>Get payment methods</strong>, then <strong>set</strong> the chosen one.</li><li><strong>Place the order</strong> to finalise the cart into an order.</li></ol><p>Calling a step out of order (e.g. asking for shipping methods before addresses are saved) is rejected — complete the earlier step first.</p><h2 id="body-shapes-to-get-right" tabindex="-1">Body Shapes to Get Right <a class="header-anchor" href="#body-shapes-to-get-right" aria-label="Permalink to &quot;Body Shapes to Get Right&quot;">​</a></h2><p>Three of the four write steps have a shape that is easy to guess wrong:</p><table tabindex="0"><thead><tr><th>Step</th><th>Send</th><th>Not</th></tr></thead><tbody><tr><td>Address</td><td>Flat <code>billingFirstName</code>, <code>billingAddress</code>, <code>billingCity</code>, … plus <code>useForShipping</code></td><td>A nested <code>billing: { … }</code> object</td></tr><tr><td>Shipping method</td><td><code>shippingMethod</code>, holding the rate&#39;s <strong><code>method</code></strong> value</td><td><code>shippingMethodCode</code>, or the rate&#39;s <code>id</code></td></tr><tr><td>Payment method</td><td><code>paymentMethod</code> as a top-level string</td><td>A nested <code>payment: { method }</code> object</td></tr><tr><td>Place order</td><td><code>{}</code></td><td>Anything — the cart already holds every choice</td></tr></tbody></table><p>The shipping rate list is where this bites most: a rate carries both <code>id</code> (<code>flatrate_flatrate_flatrate</code>) and <code>method</code> (<code>flatrate_flatrate</code>), and only <code>method</code> is accepted.</p><h2 id="failures-report-as-500-with-a-reason" tabindex="-1">Failures Report as 500 With a Reason <a class="header-anchor" href="#failures-report-as-500-with-a-reason" aria-label="Permalink to &quot;Failures Report as 500 With a Reason&quot;">​</a></h2><p>A step run out of order does not answer <code>4xx</code>. Every missing prerequisite comes back as <code>500</code> with the cause in <code>detail</code> — <code>Cart is empty</code>, <code>Billing address is required</code>, <code>Shipping method is required</code>, <code>Payment method is required</code>. Read <code>detail</code> to know which step to send the shopper back to; the status code alone says nothing.</p><h2 id="two-outcomes-when-placing-an-order" tabindex="-1">Two Outcomes When Placing an Order <a class="header-anchor" href="#two-outcomes-when-placing-an-order" aria-label="Permalink to &quot;Two Outcomes When Placing an Order&quot;">​</a></h2><p>Place Order answers <code>201</code> either way, and <code>redirect</code> decides what happens next. With <code>redirect: false</code> the order exists and <code>orderId</code> is set. With <code>redirect: true</code> there is <strong>no order yet</strong>: <code>orderId</code> is <code>null</code> and the shopper must be sent to <code>redirectUrl</code>, where the gateway creates the order once payment clears. Treating the missing <code>orderId</code> as a failure is the common mistake.</p><p>Afterwards the cart is emptied, so a repeated call fails with <code>Cart is empty</code> rather than duplicating the order. A guest order is not listed under customer orders, so capture <code>orderId</code> client-side at that moment.</p><h2 id="guest-and-customer-checkout" tabindex="-1">Guest and Customer Checkout <a class="header-anchor" href="#guest-and-customer-checkout" aria-label="Permalink to &quot;Guest and Customer Checkout&quot;">​</a></h2><p>The whole sequence works with a cart token alone — no account required. A logged-in customer sends their own Bearer token instead, and can prefill the address step from their saved addresses, though checkout stores its own copy of the address on the cart rather than referencing the address-book row.</p><h2 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to &quot;Operations&quot;">​</a></h2><p>Checkout runs as an ordered sequence. Each step depends on the one before, and the read endpoints return an empty array until their prerequisite is saved.</p><table tabindex="0"><thead><tr><th>Step</th><th>Operation</th><th>Method &amp; Path</th></tr></thead><tbody><tr><td>1</td><td><a href="/api/rest-api/shop/checkout/set-billing-address.html">Set Checkout Address</a></td><td><code>POST /api/shop/checkout-addresses</code></td></tr><tr><td>1a</td><td><a href="/api/rest-api/shop/checkout/set-shipping-address.html">Set Shipping Address</a></td><td><code>POST /api/shop/checkout-addresses</code> — the same call, with <code>useForShipping: false</code></td></tr><tr><td>2</td><td><a href="/api/rest-api/shop/checkout/get-shipping-methods.html">Get Shipping Methods</a></td><td><code>GET /api/shop/checkout-shipping-methods</code></td></tr><tr><td>3</td><td><a href="/api/rest-api/shop/checkout/set-shipping-method.html">Set Shipping Method</a></td><td><code>POST /api/shop/checkout-shipping-methods</code></td></tr><tr><td>4</td><td><a href="/api/rest-api/shop/checkout/get-payment-methods.html">Get Payment Methods</a></td><td><code>GET /api/shop/payment-methods</code></td></tr><tr><td>5</td><td><a href="/api/rest-api/shop/checkout/set-payment-method.html">Set Payment Method</a></td><td><code>POST /api/shop/checkout-payment-methods</code></td></tr><tr><td>6</td><td><a href="/api/rest-api/shop/checkout/place-order.html">Place Order</a></td><td><code>POST /api/shop/checkout-orders</code></td></tr><tr><td>—</td><td><a href="/api/rest-api/shop/checkout/get-addresses.html">Get Addresses</a></td><td><code>GET /api/shop/checkout-addresses</code> — read back what step 1 saved</td></tr></tbody></table><p>Two paths are easy to get wrong. Reading payment methods is <strong><code>GET /api/shop/payment-methods</code></strong>, not <code>checkout-payment-methods</code>, which accepts POST only. And one endpoint saves both addresses — there is no separate billing and shipping call.</p><p>All Checkout endpoints require the storefront key and the active cart&#39;s token — see <a href="/api/rest-api/authentication.html">Authentication</a>.</p>',22)]))}const m=t(s,[["render",r]]);export{u as __pageData,m as default};
